/**
 * Get VAT summary across invoices.
 * @param {any[]} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate high to low
 */
export function vatSummary(invoices) {
  const summary = new Map();

  invoices
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach(inv => {
      inv.lines.forEach(line => {
        const rate = line.vatRate ?? 0;
        const base = Math.max(0, lineTotal(line) - lineDiscount(line));
        const vat = lineVat(line);

        if (!summary.has(rate)) {
          summary.set(rate, { rate, base: 0, vat: 0 });
        }
        const entry = summary.get(rate);
        entry.base += base;
        entry.vat += vat;
      });
    });

  return Array.from(summary.values()).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice: 0.04% of amount due per day overdue.
 * @param {any} invoice
 * @param {string} asOf Date in YYYY-MM-DD format
 * @returns {number} Late fee in cents, rounded to nearest cent
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);
  const fee = amountDue * daysOverdue * 0.0004;

  return Math.round(fee);
}

