        status: 'issued',
        dueDate: '2026-10-05',
        lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
        payments: [],
      },
      {
        number: 'INV-003',
        customerId: 'CUST001',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
        payments: [],
