        payments: [],
      },
      {
        number: 'INV-002',
        customerId: 'CUST001',
        status: 'issued',
        dueDate: '2026-10-08',
        lines: [],
        payments: [],
      },
    ];
    assert.deepStrictEqual(overdueInvoices(invoices, asOf), []);
  });
});

test('vatSummary', async (t) => {
  await t.test('empty list', () => {
    assert.deepStrictEqual(vatSummary([]), []);
  });

  await t.test('single invoice with one VAT rate', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 21);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[0].vat, 21000);
  });

  await t.test('single invoice with multiple VAT rates', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
          { qty: 50, unitPrice: 2000, discountPercent: 0, vatRate: 9 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 2);
    assert.strictEqual(result[0].rate, 21);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[1].rate, 9);
    assert.strictEqual(result[1].base, 100000);
  });

  await t.test('sorts by rate high to low', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
          { qty: 20, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
          { qty: 30, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.deepStrictEqual(
      result.map(r => r.rate),
      [21, 9, 0]
    );
  });

  await t.test('includes issued, partially_paid, and paid invoices', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
      },
      {
        status: 'partially_paid',
        lines: [{ qty: 50, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
      },
      {
        status: 'paid',
        lines: [{ qty: 30, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 180000);
    assert.strictEqual(result[0].vat, 37800);
  });

  await t.test('excludes draft invoices', () => {
    const invoices = [
      {
        status: 'draft',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
      },
    ];
    assert.deepStrictEqual(vatSummary(invoices), []);
  });

  await t.test('applies discount before calculating base', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result[0].base, 90000);
    assert.strictEqual(result[0].vat, 18900);
  });

  await t.test('handles multiple invoices with same VAT rate', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
      },
      {
        status: 'issued',
        lines: [{ qty: 50, unitPrice: 2000, discountPercent: 0, vatRate: 21 }],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 200000);
    assert.strictEqual(result[0].vat, 42000);
  });

  await t.test('handles VAT rate 0', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
    assert.strictEqual(result[0].base, 100000);
    assert.strictEqual(result[0].vat, 0);
  });

  await t.test('handles lines without vatRate (defaults to 0)', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0 }],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].rate, 0);
    assert.strictEqual(result[0].base, 100000);
  });

  await t.test('aggregates multiple lines from same invoice', () => {
    const invoices = [
      {
        status: 'issued',
        lines: [
          { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
          { qty: 200, unitPrice: 500, discountPercent: 0, vatRate: 21 },
          { qty: 50, unitPrice: 2000, discountPercent: 20, vatRate: 21 },
        ],
      },
    ];
    const result = vatSummary(invoices);
    assert.strictEqual(result.length, 1);
    assert.strictEqual(result[0].base, 280000);
    assert.strictEqual(result[0].vat, 58800);
  });
});

test('lateFee', async (t) => {
  await t.test('returns 0 if invoice not overdue', () => {
    const invoice = {
      dueDate: '2026-10-10',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-10');
    assert.strictEqual(fee, 0);
  });

  await t.test('returns 0 if invoice due in the future', () => {
    const invoice = {
      dueDate: '2026-10-15',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(fee, 0);
  });

  await t.test('calculates fee for 1 day overdue', () => {
    const invoice = {
      dueDate: '2026-10-06',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const expected = Math.round(10000 * 1 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 4);
  });

  await t.test('calculates fee for multiple days overdue', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const expected = Math.round(10000 * 6 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 24);
  });

  await t.test('scales with larger amounts', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const expected = Math.round(1000000 * 6 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 2400);
  });

  await t.test('applies to amount after payments', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 6000, date: '2026-10-02' }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const amountDue = 10000 - 6000;
    const expected = Math.round(amountDue * 6 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 10);
  });

  await t.test('returns 0 if fully paid', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 10000, date: '2026-10-02' }],
    };
    const fee = lateFee(invoice, '2026-10-07');
    assert.strictEqual(fee, 0);
  });

  await t.test('rounds to nearest cent', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const expected = Math.round(12345 * 6 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 30);
  });

  await t.test('handles long overdue periods', () => {
    const invoice = {
      dueDate: '2026-01-01',
      lines: [{ qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const daysOverdue = 280;
    const expected = Math.round(50000 * daysOverdue * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 5600);
  });

  await t.test('accounts for discounts reducing due amount', () => {
    const invoice = {
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 50, vatRate: 0 }],
      payments: [],
    };
    const fee = lateFee(invoice, '2026-10-07');
    const amountDue = 5000;
    const expected = Math.round(amountDue * 6 * 0.0004);
    assert.strictEqual(fee, expected);
    assert.strictEqual(fee, 12);
  });
});
